	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		// Basic domain authentication setup
		main, err := sendgrid.NewDomainAuthentication(ctx, "main", &sendgrid.DomainAuthenticationArgs{
			Domain:            pulumi.String("mycompany.com"),
			Subdomain:         pulumi.String("em"),
			IsDefault:         pulumi.Bool(true),
			AutomaticSecurity: pulumi.Bool(true),
			CustomSpf:         pulumi.Bool(false),
		})
		if err != nil {
			return err
		}
		// Domain with custom SPF record
		_, err = sendgrid.NewDomainAuthentication(ctx, "marketing", &sendgrid.DomainAuthenticationArgs{
			Domain:            pulumi.String("marketing.mycompany.com"),
			Subdomain:         pulumi.String("mail"),
			IsDefault:         pulumi.Bool(false),
			AutomaticSecurity: pulumi.Bool(false),
			CustomSpf:         pulumi.Bool(true),
		})
		if err != nil {
			return err
		}
		// DMARC is not part of domain authentication: SendGrid neither creates nor
		// returns a _dmarc record, and the policy (p=none|quarantine|reject, rua=...)
		// is the domain owner's decision. Publish it at your DNS provider next to the
		// records SendGrid returns in `dns`. Route53 is shown; any DNS provider works.
		_, err = route53.NewRecord(ctx, "dmarc", &route53.RecordArgs{
			ZoneId: pulumi.Any(route53ZoneId),
			Name: main.Domain.ApplyT(func(domain string) (string, error) {
				return fmt.Sprintf("_dmarc.%v", domain), nil
			}).(pulumi.StringOutput),
			Type: pulumi.String(route53.RecordTypeTXT),
			Ttl:  pulumi.Int(300),
			Records: pulumi.StringArray{
				pulumi.String("v=DMARC1; p=none; rua=mailto:dmarc-reports@mycompany.com"),
			},
		})
		if err != nil {
			return err
		}
		return nil
	})
}
